import{_ as e,c as t,o as s,a4 as o}from"./chunks/framework.ttppV29E.js";const n="/assets/permission-gating-config.fJraOSY1.png",f=JSON.parse('{"title":"Permission Gating","description":"","frontmatter":{},"headers":[],"relativePath":"docs/endpoint-authentication/permission-gating.md","filePath":"docs/endpoint-authentication/permission-gating.md","lastUpdated":1791474926000}'),i={name:"docs/endpoint-authentication/permission-gating.md"},a=o('<h1 id="permission-gating" tabindex="-1">Permission Gating <a class="header-anchor" href="#permission-gating" aria-label="Permalink to &quot;Permission Gating&quot;">​</a></h1><p>Permission gating is an optional extension of <a href="/docs/endpoint-authentication/openid-connect-bearer-token.html">Open ID Connect Bearer Token</a> authentication. As well as checking that the caller&#39;s token is valid, AireGlu checks that the <strong>user behind the token holds specific permissions</strong> before the endpoint runs.</p><p>Use it when:</p><ul><li>Only some users of an application should be able to call an endpoint (for example, only users who can <code>edit:widget</code> should be able to update a widget)</li><li>The endpoint is exposed as an <a href="/docs/mcp-servers/permissions.html">MCP tool or resource</a> and should only be visible to users who are allowed to use it</li><li>Permissions are already managed centrally in AireIdentity and you don&#39;t want to repeat them in endpoint logic</li></ul><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Permission gating runs as part of authentication, after the token has been validated:</p><ol><li>The caller sends a user access token (Bearer header or form POST, see <a href="/docs/endpoint-authentication/openid-connect-bearer-token.html#how-callers-pass-a-token">How callers pass a token</a>).</li><li>AireGlu validates the token&#39;s signature, issuer, expiry, audience and scopes as normal.</li><li>AireGlu asks the <strong>permission source</strong> which permissions the user holds in each configured <strong>Target Scope</strong>, using the <strong>caller&#39;s own token</strong>.</li><li>The caller must hold <strong>every</strong> listed permission in <strong>every</strong> gated Target Scope. If anything is missing, authentication fails.</li><li>On success the endpoint runs, and the caller&#39;s token is available via liquid within the AireGlu Tasks <code>request.userToken</code>.</li></ol><h3 id="why-it-works-this-way" tabindex="-1">Why it works this way <a class="header-anchor" href="#why-it-works-this-way" aria-label="Permalink to &quot;Why it works this way&quot;">​</a></h3><ul><li><strong>The user&#39;s own token is used for the lookup.</strong> AireIdentity only returns permissions for the user the token belongs to. A caller cannot ask about anyone else&#39;s permissions, and AireGlu doesn&#39;t need a privileged service account to read them.</li><li><strong>The check is live on every request.</strong> Lookups are not cached, so revoking a role or policy in AireIdentity takes effect on the next call. There is no window where a removed user can keep calling the endpoint.</li><li><strong>It fails closed.</strong> If the permission source is unreachable, returns an error or returns nothing, the request is rejected. An outage never silently grants access.</li><li><strong>It lives on the endpoint, not on whatever calls it.</strong> The same gate applies whether the endpoint is called over HTTP, from an iframe or as an MCP tool. You configure it once.</li></ul><h2 id="configuring-permission-gating" tabindex="-1">Configuring permission gating <a class="header-anchor" href="#configuring-permission-gating" aria-label="Permalink to &quot;Configuring permission gating&quot;">​</a></h2><p>In the endpoint editor, open <strong>Authentication</strong> and add (or edit) an <strong>Open ID Connect Bearer Token</strong> method. Configure <strong>Authority</strong>, <strong>Audiences</strong> and optional <strong>Scopes</strong> as described in <a href="/docs/endpoint-authentication/openid-connect-bearer-token.html#configuring-an-endpoint">Configuring an endpoint</a>, then:</p><ol><li>Under <strong>Permission gating</strong>, tick <strong>Fetch and validate permissions for Target Scope(s)</strong>.</li><li>Choose a <strong>Permission source</strong>: <ul><li><strong>AireIdentity (default)</strong>: permissions are read live from AireIdentity&#39;s policy service.</li><li><strong>Custom Endpoint</strong>: see <a href="#custom-permission-source">Custom permission source</a>.</li></ul></li><li>For each <strong>Target Scope</strong>: <ul><li>Enter the <strong>Target Scope</strong>, the scope of the target application in AireIdentity&#39;s policy service (for example <code>PatientRecordsApi</code>).</li><li>Add the <strong>Permissions</strong> the caller must hold in that scope, in <code>action:resource</code> format (for example <code>read:patient</code>). Type each permission and press <strong>Enter</strong>.</li></ul></li><li>Click <strong>Add Target Scope</strong> to gate on further scopes.</li><li>Save the endpoint.</li></ol><p><img src="'+n+`" alt="Permission gating configured on an Open ID Connect Bearer Token method" width="473"></p><table><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>Fetch and validate permissions for Target Scope(s)</strong></td><td>No</td><td>Turns permission gating on. Unticking it removes all Target Scopes.</td></tr><tr><td><strong>Permission source</strong></td><td>Yes, when gating is on</td><td><strong>AireIdentity (default)</strong> or <strong>Custom Endpoint</strong>.</td></tr><tr><td><strong>Target Scope</strong></td><td>Yes, per row</td><td>The scope in the permission source to check. Supports <a href="/docs/getting-started/variables.html">variables</a> and <a href="/docs/getting-started/secrets.html">secrets</a>. Must not contain spaces or commas, and must be unique on the endpoint.</td></tr><tr><td><strong>Permissions</strong></td><td>No</td><td>The permissions required in that scope, in <code>action:resource</code> format. Permissions are literal values; variables are not resolved.</td></tr></tbody></table><h3 id="target-scope-vs-scopes" tabindex="-1">Target Scope vs Scopes <a class="header-anchor" href="#target-scope-vs-scopes" aria-label="Permalink to &quot;Target Scope vs Scopes&quot;">​</a></h3><p>The <strong>Scopes</strong> field and <strong>Target Scope</strong> look similar but answer different questions:</p><table><thead><tr><th></th><th><strong>Scopes</strong></th><th><strong>Target Scope</strong></th></tr></thead><tbody><tr><td>Checks</td><td>The <code>scope</code> claim inside the token</td><td>The user&#39;s permissions in AireIdentity&#39;s policy service</td></tr><tr><td>Answers</td><td>&quot;Was this token issued for this kind of call?&quot;</td><td>&quot;Is this user allowed to do this?&quot;</td></tr><tr><td>Example</td><td><code>AireGluRuntimeApi</code></td><td><code>PatientRecordsApi</code></td></tr></tbody></table><p>The Target Scope is usually the scope of the <strong>application the endpoint acts for</strong>, which is often not a scope the caller&#39;s token carries.</p><h3 id="matching-rules" tabindex="-1">Matching rules <a class="header-anchor" href="#matching-rules" aria-label="Permalink to &quot;Matching rules&quot;">​</a></h3><ul><li><strong>All</strong> Target Scopes must pass, and within each one the user must hold <strong>all</strong> listed permissions (AND, not OR). To allow &quot;either A or B&quot;, create separate endpoints or use a custom permission source.</li><li>Scope and permission names are compared case-insensitively.</li><li>A Target Scope with <strong>no permissions</strong> doesn&#39;t trigger a lookup. It still appears in <a href="#using-target-scopes-in-liquid"><code>authentication.targetScopes</code></a>, which is useful for passing a scope to a <a href="/docs/connections/delegate-exchange.html">Delegate Exchange</a> connection without gating on it.</li><li>Only one Open ID Connect Bearer Token method per endpoint version can have Target Scopes.</li><li>If the endpoint has other authentication methods, <strong>all</strong> of them must still pass.</li></ul><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><ul><li>The <strong>Authority</strong> must be your AireIdentity instance when using the AireIdentity permission source. Lookups always go to the AireIdentity instance AireGlu itself is configured with, so tokens from third-party identity providers can&#39;t be gated this way.</li><li>Users get permissions through roles and policies in AireIdentity. A user with no role granting the permission is rejected.</li></ul><h2 id="what-the-caller-sees" tabindex="-1">What the caller sees <a class="header-anchor" href="#what-the-caller-sees" aria-label="Permalink to &quot;What the caller sees&quot;">​</a></h2><table><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td>Token valid, all permissions held</td><td>Endpoint runs</td></tr><tr><td>Token valid, a permission missing</td><td><strong>401 Unauthorized</strong></td></tr><tr><td>Permission source unavailable or errors</td><td><strong>401 Unauthorized</strong> (fail closed)</td></tr><tr><td>Called as an MCP tool or resource</td><td>See <a href="/docs/mcp-servers/permissions.html">MCP Permissions</a>: the tool is hidden from the user rather than returning 401</td></tr></tbody></table><p>Rejected requests are recorded as an authentication failure in the endpoint&#39;s usage data.</p><h2 id="using-target-scopes-in-liquid" tabindex="-1">Using target scopes in Liquid <a class="header-anchor" href="#using-target-scopes-in-liquid" aria-label="Permalink to &quot;Using target scopes in Liquid&quot;">​</a></h2><p>The configured Target Scope names are available in task templates as <code>authentication.targetScopes</code>:</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ authentication.targetScopes[0] }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ authentication.targetScopes | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">join:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39; &#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span></code></pre></div><p>This contains the <strong>configured</strong> scope names (after variables are resolved), not the permissions the user holds. Its main use is to keep the scope you gate on and the scope you request downstream in step. For example, use it as the <code>scope</code> parameter of a <a href="/docs/connections/delegate-exchange.html#liquid-mapping">Delegate Exchange</a> connection.</p><p><code>authentication.targetScopes</code> is empty in Preview.</p><h2 id="permission-gating-and-downstream-calls" tabindex="-1">Permission gating and downstream calls <a class="header-anchor" href="#permission-gating-and-downstream-calls" aria-label="Permalink to &quot;Permission gating and downstream calls&quot;">​</a></h2><p>Permission gating decides <strong>whether the endpoint runs</strong>. It doesn&#39;t change the credentials the endpoint&#39;s tasks use when they call other systems.</p><p>If a task calls a downstream API <strong>as the user</strong>, use a <a href="/docs/connections/delegate-exchange.html">Delegate Exchange</a> connection. It swaps <code>request.userToken</code> for a token scoped to the downstream API. The downstream API should still enforce its own data-level access (for example, which patient records this user may see). Permission gating is the first check, not the only one.</p><p>A typical layered setup:</p><table><thead><tr><th>Layer</th><th>Question</th><th>Enforced by</th></tr></thead><tbody><tr><td>Endpoint</td><td>Can this user call this endpoint at all?</td><td>Permission gating</td></tr><tr><td>Downstream credential</td><td>What may AireGlu do on this user&#39;s behalf?</td><td>Delegate Exchange connection, Target Scope on the exchanged token</td></tr><tr><td>Data</td><td>Which records can this user see?</td><td>The downstream API</td></tr></tbody></table><h2 id="custom-permission-source" tabindex="-1">Custom permission source <a class="header-anchor" href="#custom-permission-source" aria-label="Permalink to &quot;Custom permission source&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Documentation in progress</p><p>This section is a placeholder. Documentation for using an AireGlu endpoint as a custom permission source (for applications whose permissions are not managed in AireIdentity) is coming soon.</p></div><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li><strong>Gate on the action, not the user.</strong> Grant permissions through roles and policies in AireIdentity rather than per-user, so access is managed in one place.</li><li><strong>Keep permission sets small and specific.</strong> Required permissions are ANDed, so each one you add narrows who can call the endpoint.</li><li><strong>Use one Target Scope per application.</strong> Add a second Target Scope only when the endpoint genuinely acts on two applications (for example records and billing).</li><li><strong>Don&#39;t treat gating as data security.</strong> Keep record-level checks in the downstream system, and pass the user&#39;s identity to it with a <a href="/docs/connections/delegate-exchange.html">Delegate Exchange</a> connection.</li><li><strong>Expect a lookup per request.</strong> Each gated call makes a live request to AireIdentity. For high-volume, non-user traffic, use <a href="/docs/endpoint-authentication/client-credentials.html">Client Credentials</a> on a separate endpoint instead.</li><li><strong>Test with a user who lacks the permission.</strong> Confirm they get 401 (or don&#39;t see the MCP tool) before going live.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table><thead><tr><th>Symptom</th><th>Things to check</th></tr></thead><tbody><tr><td>401 for a user who should have access</td><td>Check the user&#39;s role in AireIdentity grants <strong>every</strong> listed permission in <strong>every</strong> Target Scope. Check the Target Scope is the policy scope name, not the token&#39;s scope.</td></tr><tr><td>401 for everyone</td><td>Check <strong>Authority</strong> is your AireIdentity instance and the token is valid without gating (untick gating temporarily to isolate). Check AireIdentity is reachable from AireGlu.</td></tr><tr><td>Permission saved but rejected on save</td><td>Permissions must be <code>action:resource</code> format with no spaces or commas, for example <code>read:patient</code>.</td></tr><tr><td><code>authentication.targetScopes</code> is empty</td><td>It is always empty in Preview. Check the endpoint has an Open ID Connect Bearer Token method with at least one Target Scope.</td></tr></tbody></table>`,41),r=[a];function d(l,c,h,p,g,u){return s(),t("div",null,r)}const k=e(i,[["render",d]]);export{f as __pageData,k as default};
